 1→/** Environment variable loading and validation. */
 2→
 3→const JMAP_SESSION_URL_DEFAULT = "https://api.fastmail.com/jmap/session";
 4→const CALDAV_URL_DEFAULT = "https://caldav.fastmail.com/";
 5→
 6→export interface Config {
 7→  jmap: {
 8→    apiToken: string;
 9→    sessionUrl: string;
10→  };
11→  caldav: {
12→    username: string;
13→    appPassword: string;
14→    url: string;
15→  };
16→}
17→
18→export function loadConfig(): Config {
19→  const missing: string[] = [];
20→
21→  const apiToken = process.env.FASTMAIL_API_TOKEN;
22→  if (!apiToken) missing.push("FASTMAIL_API_TOKEN");
23→
24→  const username = process.env.FASTMAIL_USERNAME;
25→  if (!username) missing.push("FASTMAIL_USERNAME");
26→
27→  const appPassword = process.env.FASTMAIL_APP_PASSWORD;
28→  if (!appPassword) missing.push("FASTMAIL_APP_PASSWORD");
29→
30→  if (missing.length > 0) {
31→    throw new Error(
32→      `Missing required environment variables: ${missing.join(", ")}.\n` +
33→        "See https://www.fastmail.com/settings/security/tokens for API tokens\n" +
34→        "and https://www.fastmail.com/settings/security/devicekeys for app passwords."
35→    );
36→  }
37→
38→  return {
39→    jmap: {
40→      apiToken: apiToken!,
41→      sessionUrl:
42→        process.env.FASTMAIL_JMAP_SESSION_URL || JMAP_SESSION_URL_DEFAULT,
43→    },
44→    caldav: {
45→      username: username!,
46→      appPassword: appPassword!,
47→      url: process.env.FASTMAIL_CALDAV_URL || CALDAV_URL_DEFAULT,
48→    },
49→  };
50→}
