/** JMAP session bootstrap and request helper. */

import type { Config } from "../config.js";
import type {
  JmapSession,
  JmapRequest,
  JmapResponse,
  MethodResponse,
} from "./types.js";

export class JmapClient {
  private session: JmapSession | null = null;

  constructor(private config: Config["jmap"]) {}

  /** Bootstrap the JMAP session by fetching the session resource. */
  async connect(): Promise<void> {
    const res = await fetch(this.config.sessionUrl, {
      headers: { Authorization: `Bearer ${this.config.apiToken}` },
    });

    if (!res.ok) {
      throw new Error(
        `JMAP session bootstrap failed: ${res.status} ${res.statusText}`
      );
    }

    const data = (await res.json()) as Record<string, unknown>;

    const primaryAccountId = this.extractPrimaryAccountId(data);

    this.session = {
      apiUrl: data.apiUrl as string,
      accountId: primaryAccountId,
      uploadUrl: data.uploadUrl as string,
      downloadUrl: data.downloadUrl as string,
    };
  }

  /** Send a JMAP request and return the response. */
  async request(req: JmapRequest): Promise<JmapResponse> {
    if (!this.session) throw new Error("JMAP client not connected");

    const res = await fetch(this.session.apiUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${this.config.apiToken}`,
      },
      body: JSON.stringify(req),
    });

    if (!res.ok) {
      throw new Error(`JMAP request failed: ${res.status} ${res.statusText}`);
    }

    return (await res.json()) as JmapResponse;
  }

  /**
   * Convenience: send a JMAP request and return the method response
   * matching the given call ID. Throws if JMAP returned an error response.
   */
  async call(
    using: string[],
    methodCalls: JmapRequest["methodCalls"]
  ): Promise<MethodResponse[]> {
    const response = await this.request({ using, methodCalls });

    for (const [method, args] of response.methodResponses) {
      if (method === "error") {
        const err = args as { type: string; description?: string };
        throw new Error(
          `JMAP error (${err.type}): ${err.description ?? "no description"}`
        );
      }
    }

    return response.methodResponses;
  }

  get accountId(): string {
    if (!this.session) throw new Error("JMAP client not connected");
    return this.session.accountId;
  }

  get downloadUrl(): string {
    if (!this.session) throw new Error("JMAP client not connected");
    return this.session.downloadUrl;
  }

  get uploadUrl(): string {
    if (!this.session) throw new Error("JMAP client not connected");
    return this.session.uploadUrl;
  }

  /** Extract the primary mail account ID from the session object. */
  private extractPrimaryAccountId(session: Record<string, unknown>): string {
    const accounts = session.primaryAccounts as
      | Record<string, string>
      | undefined;
    if (accounts) {
      const mailAccount = accounts["urn:ietf:params:jmap:mail"];
      if (mailAccount) return mailAccount;
    }

    // Fallback: first key in accounts
    const allAccounts = session.accounts as
      | Record<string, unknown>
      | undefined;
    if (allAccounts) {
      const firstId = Object.keys(allAccounts)[0];
      if (firstId) return firstId;
    }

    throw new Error(
      "Could not determine JMAP account ID from session response"
    );
  }
}

/** Mail tool definitions: name, Zod schema, description. */

import { z } from "zod";

export const mailTools = {
  mail_list_mailboxes: {
    description: "List all mailboxes (folders) in the Fastmail account, including unread counts and folder hierarchy.",
    schema: z.object({}),
  },

  mail_search: {
    description:
      "Search and query emails with filtering, sorting, and pagination. Returns previews (not full bodies) — use mail_get for full content.",
    schema: z.object({
      query: z.string().optional().describe("Free-text search"),
      mailbox: z.string().optional().describe("Mailbox name or ID to scope the search"),
      from: z.string().optional().describe("Filter by sender"),
      to: z.string().optional().describe("Filter by recipient"),
      subject: z.string().optional().describe("Filter by subject"),
      after: z.string().optional().describe("Emails received after this ISO date"),
      before: z.string().optional().describe("Emails received before this ISO date"),
      has_attachment: z.boolean().optional().describe("Filter to emails with attachments"),
      is_unread: z.boolean().optional().describe("Filter to unread emails"),
      limit: z.number().min(1).max(100).optional().describe("Max results (default 20, max 100)"),
      position: z.number().min(0).optional().describe("0-based offset into result set (default 0)"),
    }),
  },

  mail_get: {
    description:
      "Get full details of a single email including body content. The format parameter controls body output: 'markdown' (default, best for LLM consumption), 'plain' (smallest token footprint), or 'full' (raw HTML, can be very large).",
    schema: z.object({
      id: z.string().describe("Email ID"),
      format: z
        .enum(["full", "markdown", "plain"])
        .optional()
        .describe("Body format (default: markdown)"),
    }),
  },

  mail_get_thread: {
    description: "Get all emails in a conversation thread, ordered chronologically.",
    schema: z.object({
      thread_id: z.string().describe("Thread ID"),
      format: z
        .enum(["full", "markdown", "plain"])
        .optional()
        .describe("Body format (default: markdown)"),
    }),
  },

  mail_send: {
    description: "Compose and send an email. For replies, prefer mail_reply instead.",
    schema: z.object({
      to: z.array(z.string()).describe("Recipient email addresses"),
      subject: z.string().describe("Subject line"),
      body: z.string().describe("Plain text body"),
      html_body: z.string().optional().describe("HTML body (sends multipart if provided)"),
      cc: z.array(z.string()).optional().describe("CC addresses"),
      bcc: z.array(z.string()).optional().describe("BCC addresses"),
      in_reply_to: z.string().optional().describe("Email ID this is replying to"),
      identity_id: z.string().optional().describe("Sender identity ID (defaults to primary)"),
      attachments: z
        .array(
          z.object({
            name: z.string().describe("Filename"),
            base64: z.string().describe("Base64-encoded file content"),
            content_type: z.string().describe("MIME type"),
          })
        )
        .optional()
        .describe("File attachments (max 10MB each)"),
    }),
  },

  mail_reply: {
    description:
      "Reply to an existing email. Automatically sets In-Reply-To, References, and recipient headers from the original.",
    schema: z.object({
      email_id: z.string().describe("Email ID to reply to"),
      body: z.string().describe("Reply body (plain text)"),
      html_body: z.string().optional().describe("HTML reply body"),
      reply_all: z.boolean().optional().describe("Reply to all recipients (default false)"),
    }),
  },

  mail_move: {
    description: "Move email(s) to a different mailbox (folder).",
    schema: z.object({
      email_ids: z.array(z.string()).describe("Email IDs to move"),
