 56→  private async getMailboxes(): Promise<Record<string, unknown>[]> {
 57→    const responses = await this.client.call(JMAP_USING, [
 58→      [
 59→        "Mailbox/get",
 60→        {
 61→          accountId: this.client.accountId,
 62→          properties: ["id", "name", "role", "parentId", "unreadEmails", "totalEmails", "sortOrder"],
 63→        },
 64→        "mbox0",
 65→      ],
 66→    ]);
 67→    const [, result] = responses[0];
