 77→    if (byId) return byId.id as string;
 78→
 79→    const lower = nameOrId.toLowerCase();
 80→
 81→    // Try role match first (inbox, drafts, sent, trash, junk, archive)
 82→    const byRole = mailboxes.find((m) => (m.role as string | null)?.toLowerCase() === lower);
 83→    if (byRole) return byRole.id as string;
 84→
 85→    // Try name match (case-insensitive)
 86→    const byName = mailboxes.find((m) => (m.name as string).toLowerCase() === lower);
 87→    if (byName) return byName.id as string;
 88→
 89→    throw new Error(`Mailbox not found: "${nameOrId}"`);
 90→  }
 91→
 92→  // --- Tool handlers ---
 93→
 94→  async listMailboxes(): Promise<Record<string, unknown>[]> {
 95→    return this.getMailboxes();
 96→  }
