 98→  async search(params: {
 99→    query?: string;
100→    mailbox?: string;
101→    from?: string;
102→    to?: string;
103→    subject?: string;
104→    after?: string;
105→    before?: string;
106→    has_attachment?: boolean;
107→    is_unread?: boolean;
108→    limit?: number;
109→    position?: number;
110→  }) {
111→    const filter: Record<string, unknown> = {};
112→
113→    if (params.query) filter.text = params.query;
114→    if (params.from) filter.from = params.from;
115→    if (params.to) filter.to = params.to;
116→    if (params.subject) filter.subject = params.subject;
117→    if (params.after) filter.after = new Date(params.after).toISOString();
118→    if (params.before) filter.before = new Date(params.before).toISOString();
119→    if (params.has_attachment !== undefined) filter.hasAttachment = params.has_attachment;
120→    if (params.is_unread !== undefined) filter.hasKeyword = params.is_unread ? undefined : "$seen";
121→
122→    if (params.is_unread === true) {
123→      filter.notKeyword = "$seen";
124→    } else if (params.is_unread === false) {
125→      filter.hasKeyword = "$seen";
126→    }
127→
128→    if (params.mailbox) {
129→      const mailboxId = await this.resolveMailboxId(params.mailbox);
130→      filter.inMailbox = mailboxId;
131→    }
132→
133→    const limit = params.limit ?? 20;
134→    const position = params.position ?? 0;
135→
136→    const responses = await this.client.call(JMAP_USING, [
137→      [
138→        "Email/query",
139→        {
140→          accountId: this.client.accountId,
141→          filter,
142→          sort: [{ property: "receivedAt", isAscending: false }],
143→          position,
144→          limit,
145→          calculateTotal: true,
146→        },
147→        "q0",
148→      ],
149→      [
150→        "Email/get",
151→        {
152→          accountId: this.client.accountId,
153→          "#ids": { resultOf: "q0", name: "Email/query", path: "/ids" },
154→          properties: SEARCH_PROPERTIES,
155→        },
156→        "g0",
157→      ],
158→    ]);
159→
160→    const queryResult = responses[0][1] as { total: number; position: number };
161→    const getResult = responses[1][1] as { list: Record<string, unknown>[] };
162→
163→    const emails = getResult.list.map((e) => ({
164→      id: e.id,
165→      threadId: e.threadId,
166→      subject: e.subject,
167→      from: e.from,
168→      to: e.to,
169→      receivedAt: e.receivedAt,
170→      preview: e.preview,
171→      isUnread: !(e.keywords as Record<string, boolean>)?.["$seen"],
172→      isFlagged: !!(e.keywords as Record<string, boolean>)?.["$flagged"],
173→      hasAttachment: e.hasAttachment,
174→    }));
175→
176→    return {
177→      emails,
178→      position,
179→      total: queryResult.total,
180→      has_more: position + emails.length < queryResult.total,
181→    };
182→  }
