184→  async getEmail(params: { id: string; format?: "full" | "markdown" | "plain" }) {
185→    const format = params.format ?? "markdown";
186→
187→    const responses = await this.client.call(JMAP_USING, [
188→      [
189→        "Email/get",
190→        {
191→          accountId: this.client.accountId,
192→          ids: [params.id],
193→          properties: FULL_PROPERTIES,
194→          fetchAllBodyValues: true,
195→        },
196→        "g0",
197→      ],
198→    ]);
199→
200→    const result = responses[0][1] as { list: Record<string, unknown>[]; notFound: string[] };
201→    if (result.notFound?.length) {
202→      throw new Error(`Email not found: ${params.id}`);
203→    }
204→
205→    const email = result.list[0];
206→    return this.formatEmail(email, format);
207→  }
