209→  async getThread(params: { thread_id: string; format?: "full" | "markdown" | "plain" }) {
210→    const format = params.format ?? "markdown";
211→
212→    const responses = await this.client.call(JMAP_USING, [
213→      [
214→        "Thread/get",
215→        {
216→          accountId: this.client.accountId,
217→          ids: [params.thread_id],
218→        },
219→        "t0",
220→      ],
221→      [
222→        "Email/get",
223→        {
224→          accountId: this.client.accountId,
225→          "#ids": { resultOf: "t0", name: "Thread/get", path: "/list/*/emailIds" },
226→          properties: FULL_PROPERTIES,
227→          fetchAllBodyValues: true,
228→        },
229→        "g0",
230→      ],
231→    ]);
232→
233→    const threadResult = responses[0][1] as { list: { emailIds: string[] }[]; notFound: string[] };
234→    if (threadResult.notFound?.length) {
235→      throw new Error(`Thread not found: ${params.thread_id}`);
236→    }
237→
238→    const getResult = responses[1][1] as { list: Record<string, unknown>[] };
239→
240→    // Sort chronologically
241→    const sorted = getResult.list.sort(
242→      (a, b) =>
243→        new Date(a.receivedAt as string).getTime() - new Date(b.receivedAt as string).getTime()
244→    );
245→
246→    return sorted.map((email) => this.formatEmail(email, format));
247→  }
248→
249→  async send(params: {
250→    to: string[];
251→    subject: string;
252→    body: string;
253→    html_body?: string;
254→    cc?: string[];
255→    bcc?: string[];
256→    in_reply_to?: string;
257→    identity_id?: string;
258→    attachments?: { name: string; base64: string; content_type: string }[];
259→  }) {
260→    // Resolve identity
261→    let identityId = params.identity_id;
262→    if (!identityId) {
263→      const identities = await this.getIdentities();
264→      const defaultId = identities.find((i) => i.isDefault) ?? identities[0];
265→      if (!defaultId) throw new Error("No sender identity found");
266→      identityId = defaultId.id as string;
267→    }
268→
269→    // Handle reply headers
270→    let threadId: string | undefined;
271→    let inReplyToHeader: string | undefined;
272→    let referencesHeader: string | undefined;
273→
274→    if (params.in_reply_to) {
275→      const original = await this.getEmail({ id: params.in_reply_to, format: "plain" });
276→      threadId = original.threadId as string;
277→
278→      const messageId = (original.headers as Record<string, string>)?.["Message-Id"];
279→      if (messageId) {
280→        inReplyToHeader = messageId;
281→        const existingRefs = (original.headers as Record<string, string>)?.["References"] ?? "";
282→        referencesHeader = existingRefs ? `${existingRefs} ${messageId}` : messageId;
283→      }
284→    }
285→
286→    // Upload attachments
287→    const blobIds: { blobId: string; name: string; type: string; size: number }[] = [];
288→    if (params.attachments) {
289→      for (const att of params.attachments) {
290→        const data = Buffer.from(att.base64, "base64");
291→        const res = await fetch(
292→          this.client.uploadUrl.replace("{accountId}", this.client.accountId),
293→          {
294→            method: "POST",
295→            headers: {
296→              "Content-Type": att.content_type,
297→              Authorization: `Bearer ${this.client["config"].apiToken}`,
298→            },
299→            body: data,
300→          }
301→        );
302→        if (!res.ok) throw new Error(`Attachment upload failed: ${res.status}`);
303→        const blob = (await res.json()) as { blobId: string; size: number };
304→        blobIds.push({ blobId: blob.blobId, name: att.name, type: att.content_type, size: blob.size });
305→      }
306→    }
307→
308→    // Resolve drafts mailbox
309→    const draftsId = await this.resolveMailboxId("drafts");
310→
311→    // Build email body parts
312→    const bodyParts: Record<string, unknown>[] = [];
313→    const bodyValues: Record<string, { value: string; isEncodingProblem: boolean }> = {};
314→
315→    bodyParts.push({ partId: "text", type: "text/plain" });
316→    bodyValues["text"] = { value: params.body, isEncodingProblem: false };
317→
318→    if (params.html_body) {
319→      bodyParts.push({ partId: "html", type: "text/html" });
320→      bodyValues["html"] = { value: params.html_body, isEncodingProblem: false };
321→    }
322→
323→    // Build email create object
324→    const emailCreate: Record<string, unknown> = {
325→      mailboxIds: { [draftsId]: true },
326→      from: undefined, // filled by identity
327→      to: params.to.map((email) => ({ email })),
328→      subject: params.subject,
329→      keywords: { $seen: true, $draft: true },
330→      bodyValues,
331→      textBody: [{ partId: "text", type: "text/plain" }],
332→    };
333→
334→    if (params.html_body) {
335→      emailCreate.htmlBody = [{ partId: "html", type: "text/html" }];
336→    }
337→
338→    if (params.cc) emailCreate.cc = params.cc.map((email) => ({ email }));
339→    if (params.bcc) emailCreate.bcc = params.bcc.map((email) => ({ email }));
340→    if (threadId) emailCreate.threadId = threadId;
341→
342→    const headers: Record<string, string>[] = [];
343→    if (inReplyToHeader) headers.push({ "header:In-Reply-To:asText": inReplyToHeader });
344→    if (referencesHeader) headers.push({ "header:References:asText": referencesHeader });
345→    if (headers.length) Object.assign(emailCreate, ...headers);
346→
347→    if (blobIds.length) {
348→      emailCreate.attachments = blobIds.map((b) => ({
349→        blobId: b.blobId,
350→        name: b.name,
351→        type: b.type,
352→        size: b.size,
353→      }));
354→    }
355→
356→    // Create email + submit
357→    const responses = await this.client.call(JMAP_USING, [
358→      [
359→        "Email/set",
360→        {
361→          accountId: this.client.accountId,
362→          create: { draft: emailCreate },
363→        },
364→        "e0",
365→      ],
366→      [
367→        "EmailSubmission/set",
368→        {
369→          accountId: this.client.accountId,
370→          create: {
371→            sub: {
372→              identityId,
373→              emailId: "#draft",
374→            },
375→          },
376→          onSuccessUpdateEmail: {
377→            "#sub": {
378→              "mailboxIds/drafts": null,
379→              [`mailboxIds/${await this.resolveMailboxId("sent")}`]: true,
380→              "keywords/$draft": null,
381→            },
382→          },
383→        },
384→        "s0",
385→      ],
386→    ]);
387→
388→    const emailResult = responses[0][1] as { created?: Record<string, { id: string; threadId: string }> };
389→    const subResult = responses[1][1] as { created?: Record<string, { id: string }> };
390→
391→    const createdEmail = emailResult.created?.draft;
392→    const createdSub = subResult.created?.sub;
393→
394→    return {
395→      id: createdEmail?.id,
396→      threadId: createdEmail?.threadId,
397→      emailSubmissionId: createdSub?.id,
398→    };
399→  }
400→
401→  async reply(params: {
402→    email_id: string;
403→    body: string;
404→    html_body?: string;
405→    reply_all?: boolean;
406→  }) {
407→    const original = await this.getEmail({ id: params.email_id, format: "plain" });
408→
409→    // Build recipient list
410→    const fromAddresses = original.from as { name: string; email: string }[];
411→    let toAddresses = fromAddresses.map((a) => a.email);
412→
413→    if (params.reply_all) {
414→      const toOriginal = (original.to as { name: string; email: string }[]) ?? [];
415→      const ccOriginal = (original.cc as { name: string; email: string }[]) ?? [];
416→
417→      // Get our identities to exclude ourselves
418→      const identities = await this.getIdentities();
419→      const ourEmails = new Set(identities.map((i) => (i.email as string).toLowerCase()));
420→
421→      const allRecipients = [...toOriginal, ...ccOriginal]
422→        .map((a) => a.email)
423→        .filter((e) => !ourEmails.has(e.toLowerCase()));
424→
425→      toAddresses = [...new Set([...toAddresses, ...allRecipients])];
426→    }
427→
428→    const originalSubject = original.subject as string;
429→    const subject = originalSubject.startsWith("Re:") ? originalSubject : `Re: ${originalSubject}`;
430→
431→    return this.send({
432→      to: toAddresses,
433→      subject,
434→      body: params.body,
435→      html_body: params.html_body,
436→      in_reply_to: params.email_id,
437→    });
438→  }
439→
440→  async move(params: { email_ids: string[]; to_mailbox: string }) {
441→    const mailboxId = await this.resolveMailboxId(params.to_mailbox);
442→
443→    // First get current mailboxIds for each email
444→    const getResponses = await this.client.call(JMAP_USING, [
445→      [
446→        "Email/get",
447→        {
448→          accountId: this.client.accountId,
449→          ids: params.email_ids,
450→          properties: ["mailboxIds"],
451→        },
452→        "g0",
453→      ],
454→    ]);
455→
456→    const emails = (getResponses[0][1] as { list: { id: string; mailboxIds: Record<string, boolean> }[] }).list;
457→
458→    const update: Record<string, Record<string, unknown>> = {};
459→    for (const email of emails) {
460→      const patch: Record<string, unknown> = {};
461→      // Remove from all current mailboxes
462→      for (const oldId of Object.keys(email.mailboxIds)) {
463→        patch[`mailboxIds/${oldId}`] = null;
464→      }
465→      // Add to destination
466→      patch[`mailboxIds/${mailboxId}`] = true;
467→      update[email.id] = patch;
468→    }
469→
470→    await this.client.call(JMAP_USING, [
471→      [
472→        "Email/set",
473→        {
474→          accountId: this.client.accountId,
475→          update,
476→        },
477→        "m0",
478→      ],
479→    ]);
480→
481→    return { moved: params.email_ids.length };
482→  }
483→
484→  async updateFlags(params: {
485→    email_ids: string[];
486→    set_flags?: string[];
487→    clear_flags?: string[];
488→  }) {
489→    const update: Record<string, Record<string, unknown>> = {};
490→
491→    for (const id of params.email_ids) {
492→      const patch: Record<string, unknown> = {};
493→      if (params.set_flags) {
494→        for (const flag of params.set_flags) {
495→          patch[`keywords/${flag}`] = true;
496→        }
497→      }
498→      if (params.clear_flags) {
499→        for (const flag of params.clear_flags) {
500→          patch[`keywords/${flag}`] = null;
501→        }
502→      }
503→      update[id] = patch;
504→    }
505→
506→    await this.client.call(JMAP_USING, [
507→      [
508→        "Email/set",
509→        {
510→          accountId: this.client.accountId,
511→          update,
512→        },
513→        "f0",
514→      ],
515→    ]);
516→
517→    return { updated: params.email_ids.length };
518→  }
519→
520→  async deleteEmails(params: { email_ids: string[]; permanent?: boolean }) {
521→    if (params.permanent) {
522→      await this.client.call(JMAP_USING, [
523→        [
524→          "Email/set",
525→          {
526→            accountId: this.client.accountId,
527→            destroy: params.email_ids,
528→          },
529→          "d0",
530→        ],
531→      ]);
