533→    }
534→
535→    // Move to trash
536→    const trashId = await this.resolveMailboxId("trash");
537→    await this.move({ email_ids: params.email_ids, to_mailbox: trashId });
538→    return { deleted: params.email_ids.length, permanent: false };
