541→  async createMailbox(params: { name: string; parent_id?: string }) {
542→    const create: Record<string, unknown> = { name: params.name };
543→    if (params.parent_id) create.parentId = params.parent_id;
544→
545→    const responses = await this.client.call(JMAP_USING, [
546→      [
547→        "Mailbox/set",
548→        {
549→          accountId: this.client.accountId,
550→          create: { mb: create },
551→        },
552→        "c0",
553→      ],
554→    ]);
555→
556→    const result = responses[0][1] as { created?: Record<string, { id: string }> };
557→    const created = result.created?.mb;
558→    return { id: created?.id, name: params.name };
559→  }
560→
561→  async downloadAttachment(params: {
562→    email_id: string;
563→    blob_id: string;
564→    save_to_disk?: boolean;
565→  }) {
566→    // Get email to find attachment metadata
567→    const responses = await this.client.call(JMAP_USING, [
568→      [
569→        "Email/get",
570→        {
571→          accountId: this.client.accountId,
572→          ids: [params.email_id],
573→          properties: ["attachments"],
574→        },
575→        "g0",
576→      ],
577→    ]);
578→
579→    const email = (responses[0][1] as { list: Record<string, unknown>[] }).list[0];
580→    const attachments = (email?.attachments ?? []) as {
581→      blobId: string;
582→      name: string;
583→      type: string;
584→      size: number;
585→    }[];
586→    const attachment = attachments.find((a) => a.blobId === params.blob_id);
587→    if (!attachment) throw new Error(`Attachment not found: ${params.blob_id}`);
588→
589→    // Download blob
590→    const url = this.client.downloadUrl
591→      .replace("{accountId}", this.client.accountId)
592→      .replace("{blobId}", params.blob_id)
593→      .replace("{name}", encodeURIComponent(attachment.name))
594→      .replace("{type}", encodeURIComponent(attachment.type));
595→
596→    const res = await fetch(url, {
597→      headers: { Authorization: `Bearer ${this.client["config"].apiToken}` },
598→    });
599→    if (!res.ok) throw new Error(`Blob download failed: ${res.status}`);
600→
601→    const data = Buffer.from(await res.arrayBuffer());
602→
603→    // Return inline or save to disk
604→    const shouldSaveToDisk = params.save_to_disk || data.length > 1_000_000;
605→
606→    if (shouldSaveToDisk) {
607→      const dir = join(tmpdir(), "fastmail-mcp");
608→      await mkdir(dir, { recursive: true });
609→      const filePath = join(dir, `${params.blob_id}-${attachment.name}`);
610→      await writeFile(filePath, data);
611→
612→      return {
613→        filename: attachment.name,
614→        content_type: attachment.type,
615→        size: data.length,
616→        path: filePath,
617→      };
618→    }
619→
620→    return {
621→      filename: attachment.name,
622→      content_type: attachment.type,
623→      size: data.length,
624→      data: data.toString("base64"),
625→    };
626→  }
627→
628→  async getIdentities(): Promise<Record<string, unknown>[]> {
629→    const responses = await this.client.call(JMAP_USING, [
630→      [
631→        "Identity/get",
632→        { accountId: this.client.accountId },
633→        "i0",
634→      ],
635→    ]);
636→
637→    const result = responses[0][1] as { list: Record<string, unknown>[] };
638→    return result.list.map((i) => ({
639→      id: i.id,
640→      name: i.name,
641→      email: i.email,
642→      isDefault: i.isDefault ?? false,
643→    }));
644→  }
645→
646→  // --- Format helpers ---
647→
648→  private formatEmail(email: Record<string, unknown>, format: "full" | "markdown" | "plain") {
649→    const bodyValues = email.bodyValues as Record<string, { value: string }> | undefined;
650→
651→    let body = "";
652→    let bodyFormat: "html" | "markdown" | "plain" = "plain";
653→
654→    if (format === "plain") {
655→      const textParts = email.textBody as { partId: string }[] | undefined;
656→      if (textParts?.length && bodyValues) {
657→        body = textParts.map((p) => bodyValues[p.partId]?.value ?? "").join("\n");
658→      }
659→      bodyFormat = "plain";
660→    } else {
661→      // Get HTML body
662→      const htmlParts = email.htmlBody as { partId: string }[] | undefined;
663→      let htmlBody = "";
664→      if (htmlParts?.length && bodyValues) {
665→        htmlBody = htmlParts.map((p) => bodyValues[p.partId]?.value ?? "").join("\n");
666→      }
667→
668→      if (format === "full") {
669→        body = htmlBody;
670→        bodyFormat = "html";
671→      } else {
672→        // markdown
673→        if (htmlBody) {
674→          body = turndown.turndown(htmlBody);
675→          bodyFormat = "markdown";
676→        } else {
677→          // Fallback to text body
678→          const textParts = email.textBody as { partId: string }[] | undefined;
679→          if (textParts?.length && bodyValues) {
680→            body = textParts.map((p) => bodyValues[p.partId]?.value ?? "").join("\n");
681→          }
682→          bodyFormat = "plain";
683→        }
684→      }
685→    }
686→
687→    return {
688→      id: email.id,
689→      threadId: email.threadId,
690→      mailboxIds: email.mailboxIds,
691→      subject: email.subject,
692→      from: email.from,
693→      to: email.to,
694→      cc: email.cc,
695→      bcc: email.bcc,
696→      replyTo: email.replyTo,
697→      sentAt: email.sentAt,
698→      receivedAt: email.receivedAt,
699→      preview: email.preview,
700→      body,
701→      bodyFormat,
702→      attachments: email.attachments ?? [],
703→      keywords: email.keywords,
704→      headers: email.headers,
705→    };
706→  }
707→}
