/** Mail tool handler implementations. */

import { tmpdir } from "node:os";
import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";
import TurndownService from "turndown";
import type { JmapClient } from "./client.js";

const JMAP_USING = [
  "urn:ietf:params:jmap:core",
  "urn:ietf:params:jmap:mail",
  "urn:ietf:params:jmap:submission",
];

const SEARCH_PROPERTIES = [
  "id",
  "threadId",
  "subject",
  "from",
  "to",
  "receivedAt",
  "preview",
  "keywords",
  "hasAttachment",
];

const FULL_PROPERTIES = [
  "id",
  "threadId",
  "mailboxIds",
  "subject",
  "from",
  "to",
  "cc",
  "bcc",
  "replyTo",
  "sentAt",
  "receivedAt",
  "preview",
  "bodyValues",
  "htmlBody",
  "textBody",
  "attachments",
  "keywords",
  "hasAttachment",
  "headers",
];

const turndown = new TurndownService({ headingStyle: "atx", codeBlockStyle: "fenced" });

export class MailHandlers {
  constructor(private client: JmapClient) {}

  // --- Mailbox helpers ---

  private async getMailboxes(): Promise<Record<string, unknown>[]> {
    const responses = await this.client.call(JMAP_USING, [
      [
        "Mailbox/get",
        {
          accountId: this.client.accountId,
          properties: ["id", "name", "role", "parentId", "unreadEmails", "totalEmails", "sortOrder"],
        },
        "mbox0",
      ],
    ]);
    const [, result] = responses[0];
    return (result as { list: Record<string, unknown>[] }).list;
  }

  /** Resolve a mailbox name or ID to a mailbox ID. */
  private async resolveMailboxId(nameOrId: string): Promise<string> {
    const mailboxes = await this.getMailboxes();

    // Try direct ID match
    const byId = mailboxes.find((m) => m.id === nameOrId);
    if (byId) return byId.id as string;

    const lower = nameOrId.toLowerCase();

    // Try role match first (inbox, drafts, sent, trash, junk, archive)
    const byRole = mailboxes.find((m) => (m.role as string | null)?.toLowerCase() === lower);
    if (byRole) return byRole.id as string;

    // Try name match (case-insensitive)
    const byName = mailboxes.find((m) => (m.name as string).toLowerCase() === lower);
    if (byName) return byName.id as string;

    throw new Error(`Mailbox not found: "${nameOrId}"`);
  }

  // --- Tool handlers ---

  async listMailboxes(): Promise<Record<string, unknown>[]> {
    return this.getMailboxes();
  }

  async search(params: {
    query?: string;
    mailbox?: string;
    from?: string;
    to?: string;
    subject?: string;
    after?: string;
    before?: string;
    has_attachment?: boolean;
    is_unread?: boolean;
    limit?: number;
    position?: number;
  }) {
    const filter: Record<string, unknown> = {};

    if (params.query) filter.text = params.query;
    if (params.from) filter.from = params.from;
    if (params.to) filter.to = params.to;
    if (params.subject) filter.subject = params.subject;
    if (params.after) filter.after = new Date(params.after).toISOString();
    if (params.before) filter.before = new Date(params.before).toISOString();
    if (params.has_attachment !== undefined) filter.hasAttachment = params.has_attachment;
    if (params.is_unread !== undefined) filter.hasKeyword = params.is_unread ? undefined : "$seen";

    if (params.is_unread === true) {
      filter.notKeyword = "$seen";
    } else if (params.is_unread === false) {
      filter.hasKeyword = "$seen";
    }

    if (params.mailbox) {
      const mailboxId = await this.resolveMailboxId(params.mailbox);
      filter.inMailbox = mailboxId;
    }

    const limit = params.limit ?? 20;
    const position = params.position ?? 0;

    const responses = await this.client.call(JMAP_USING, [
      [
        "Email/query",
        {
          accountId: this.client.accountId,
          filter,
          sort: [{ property: "receivedAt", isAscending: false }],
          position,
          limit,
          calculateTotal: true,
        },
        "q0",
      ],
      [
        "Email/get",
        {
          accountId: this.client.accountId,
          "#ids": { resultOf: "q0", name: "Email/query", path: "/ids" },
          properties: SEARCH_PROPERTIES,
        },
        "g0",
      ],
    ]);

    const queryResult = responses[0][1] as { total: number; position: number };
    const getResult = responses[1][1] as { list: Record<string, unknown>[] };

    const emails = getResult.list.map((e) => ({
      id: e.id,
      threadId: e.threadId,
      subject: e.subject,
      from: e.from,
      to: e.to,
      receivedAt: e.receivedAt,
      preview: e.preview,
      isUnread: !(e.keywords as Record<string, boolean>)?.["$seen"],
      isFlagged: !!(e.keywords as Record<string, boolean>)?.["$flagged"],
      hasAttachment: e.hasAttachment,
    }));

    return {
      emails,
      position,
      total: queryResult.total,
      has_more: position + emails.length < queryResult.total,
    };
  }

  async getEmail(params: { id: string; format?: "full" | "markdown" | "plain" }) {
    const format = params.format ?? "markdown";

    const responses = await this.client.call(JMAP_USING, [
      [
        "Email/get",
        {
          accountId: this.client.accountId,
          ids: [params.id],
          properties: FULL_PROPERTIES,
          fetchAllBodyValues: true,
        },
        "g0",
      ],
    ]);

    const result = responses[0][1] as { list: Record<string, unknown>[]; notFound: string[] };
    if (result.notFound?.length) {
      throw new Error(`Email not found: ${params.id}`);
    }

    const email = result.list[0];
    return this.formatEmail(email, format);
  }

  async getThread(params: { thread_id: string; format?: "full" | "markdown" | "plain" }) {
    const format = params.format ?? "markdown";

    const responses = await this.client.call(JMAP_USING, [
      [
        "Thread/get",
        {
          accountId: this.client.accountId,
          ids: [params.thread_id],
        },
        "t0",
      ],
      [
        "Email/get",
        {
          accountId: this.client.accountId,
          "#ids": { resultOf: "t0", name: "Thread/get", path: "/list/*/emailIds" },
          properties: FULL_PROPERTIES,
          fetchAllBodyValues: true,
        },
        "g0",
      ],
    ]);

    const threadResult = responses[0][1] as { list: { emailIds: string[] }[]; notFound: string[] };
    if (threadResult.notFound?.length) {
      throw new Error(`Thread not found: ${params.thread_id}`);
    }

    const getResult = responses[1][1] as { list: Record<string, unknown>[] };

    // Sort chronologically
    const sorted = getResult.list.sort(
      (a, b) =>
        new Date(a.receivedAt as string).getTime() - new Date(b.receivedAt as string).getTime()
    );

    return sorted.map((email) => this.formatEmail(email, format));
  }

  async send(params: {
    to: string[];
    subject: string;
    body: string;
    html_body?: string;
    cc?: string[];
    bcc?: string[];
    in_reply_to?: string;
    identity_id?: string;
    attachments?: { name: string; base64: string; content_type: string }[];
  }) {
    // Resolve identity
    let identityId = params.identity_id;
    if (!identityId) {
      const identities = await this.getIdentities();
      const defaultId = identities.find((i) => i.isDefault) ?? identities[0];
      if (!defaultId) throw new Error("No sender identity found");
      identityId = defaultId.id as string;
    }

    // Handle reply headers
    let threadId: string | undefined;
    let inReplyToHeader: string | undefined;
    let referencesHeader: string | undefined;

    if (params.in_reply_to) {
      const original = await this.getEmail({ id: params.in_reply_to, format: "plain" });
      threadId = original.threadId as string;

      const messageId = (original.headers as Record<string, string>)?.["Message-Id"];
      if (messageId) {
        inReplyToHeader = messageId;
        const existingRefs = (original.headers as Record<string, string>)?.["References"] ?? "";
        referencesHeader = existingRefs ? `${existingRefs} ${messageId}` : messageId;
      }
    }

    // Upload attachments
    const blobIds: { blobId: string; name: string; type: string; size: number }[] = [];
    if (params.attachments) {
      for (const att of params.attachments) {
        const data = Buffer.from(att.base64, "base64");
        const res = await fetch(
          this.client.uploadUrl.replace("{accountId}", this.client.accountId),
          {
            method: "POST",
            headers: {
              "Content-Type": att.content_type,
              Authorization: `Bearer ${this.client["config"].apiToken}`,
            },
            body: data,
          }
        );
        if (!res.ok) throw new Error(`Attachment upload failed: ${res.status}`);
        const blob = (await res.json()) as { blobId: string; size: number };
        blobIds.push({ blobId: blob.blobId, name: att.name, type: att.content_type, size: blob.size });
      }
    }

    // Resolve drafts mailbox
    const draftsId = await this.resolveMailboxId("drafts");

    // Build email body parts
    const bodyParts: Record<string, unknown>[] = [];
    const bodyValues: Record<string, { value: string; isEncodingProblem: boolean }> = {};

    bodyParts.push({ partId: "text", type: "text/plain" });
    bodyValues["text"] = { value: params.body, isEncodingProblem: false };

    if (params.html_body) {
      bodyParts.push({ partId: "html", type: "text/html" });
      bodyValues["html"] = { value: params.html_body, isEncodingProblem: false };
    }

    // Build email create object
    const emailCreate: Record<string, unknown> = {
      mailboxIds: { [draftsId]: true },
      from: undefined, // filled by identity
      to: params.to.map((email) => ({ email })),
      subject: params.subject,
      keywords: { $seen: true, $draft: true },
      bodyValues,
      textBody: [{ partId: "text", type: "text/plain" }],
    };

    if (params.html_body) {
      emailCreate.htmlBody = [{ partId: "html", type: "text/html" }];
    }

    if (params.cc) emailCreate.cc = params.cc.map((email) => ({ email }));
    if (params.bcc) emailCreate.bcc = params.bcc.map((email) => ({ email }));
    if (threadId) emailCreate.threadId = threadId;

    const headers: Record<string, string>[] = [];
    if (inReplyToHeader) headers.push({ "header:In-Reply-To:asText": inReplyToHeader });
    if (referencesHeader) headers.push({ "header:References:asText": referencesHeader });
    if (headers.length) Object.assign(emailCreate, ...headers);

    if (blobIds.length) {
      emailCreate.attachments = blobIds.map((b) => ({
        blobId: b.blobId,
        name: b.name,
        type: b.type,
        size: b.size,
      }));
    }

    // Create email + submit
    const responses = await this.client.call(JMAP_USING, [
      [
        "Email/set",
        {
          accountId: this.client.accountId,
          create: { draft: emailCreate },
        },
        "e0",
      ],
      [
        "EmailSubmission/set",
        {
          accountId: this.client.accountId,
          create: {
            sub: {
              identityId,
              emailId: "#draft",
            },
          },
          onSuccessUpdateEmail: {
            "#sub": {
              "mailboxIds/drafts": null,
              [`mailboxIds/${await this.resolveMailboxId("sent")}`]: true,
              "keywords/$draft": null,
            },
          },
        },
        "s0",
      ],
    ]);

    const emailResult = responses[0][1] as { created?: Record<string, { id: string; threadId: string }> };
    const subResult = responses[1][1] as { created?: Record<string, { id: string }> };

    const createdEmail = emailResult.created?.draft;
    const createdSub = subResult.created?.sub;

    return {
      id: createdEmail?.id,
      threadId: createdEmail?.threadId,
      emailSubmissionId: createdSub?.id,
    };
  }

  async reply(params: {
    email_id: string;
    body: string;
    html_body?: string;
    reply_all?: boolean;
  }) {
    const original = await this.getEmail({ id: params.email_id, format: "plain" });

    // Build recipient list
    const fromAddresses = original.from as { name: string; email: string }[];
    let toAddresses = fromAddresses.map((a) => a.email);

    if (params.reply_all) {
      const toOriginal = (original.to as { name: string; email: string }[]) ?? [];
      const ccOriginal = (original.cc as { name: string; email: string }[]) ?? [];

      // Get our identities to exclude ourselves
      const identities = await this.getIdentities();
      const ourEmails = new Set(identities.map((i) => (i.email as string).toLowerCase()));

      const allRecipients = [...toOriginal, ...ccOriginal]
        .map((a) => a.email)
        .filter((e) => !ourEmails.has(e.toLowerCase()));

      toAddresses = [...new Set([...toAddresses, ...allRecipients])];
    }

    const originalSubject = original.subject as string;
    const subject = originalSubject.startsWith("Re:") ? originalSubject : `Re: ${originalSubject}`;

    return this.send({
      to: toAddresses,
      subject,
      body: params.body,
      html_body: params.html_body,
      in_reply_to: params.email_id,
    });
  }

  async move(params: { email_ids: string[]; to_mailbox: string }) {
    const mailboxId = await this.resolveMailboxId(params.to_mailbox);

    // First get current mailboxIds for each email
    const getResponses = await this.client.call(JMAP_USING, [
      [
        "Email/get",
        {
          accountId: this.client.accountId,
          ids: params.email_ids,
          properties: ["mailboxIds"],
        },
        "g0",
      ],
    ]);

    const emails = (getResponses[0][1] as { list: { id: string; mailboxIds: Record<string, boolean> }[] }).list;

    const update: Record<string, Record<string, unknown>> = {};
    for (const email of emails) {
      const patch: Record<string, unknown> = {};
      // Remove from all current mailboxes
      for (const oldId of Object.keys(email.mailboxIds)) {
        patch[`mailboxIds/${oldId}`] = null;
      }
      // Add to destination
      patch[`mailboxIds/${mailboxId}`] = true;
      update[email.id] = patch;
    }

    await this.client.call(JMAP_USING, [
      [
        "Email/set",
        {
          accountId: this.client.accountId,
          update,
        },
        "m0",
      ],
    ]);

    return { moved: params.email_ids.length };
  }

  async updateFlags(params: {
    email_ids: string[];
    set_flags?: string[];
    clear_flags?: string[];
  }) {
    const update: Record<string, Record<string, unknown>> = {};

    for (const id of params.email_ids) {
      const patch: Record<string, unknown> = {};
      if (params.set_flags) {
        for (const flag of params.set_flags) {
          patch[`keywords/${flag}`] = true;
        }
      }
      if (params.clear_flags) {
        for (const flag of params.clear_flags) {
          patch[`keywords/${flag}`] = null;
        }
      }
      update[id] = patch;
    }

    await this.client.call(JMAP_USING, [
      [
        "Email/set",
        {
          accountId: this.client.accountId,
          update,
        },
        "f0",
      ],
    ]);

    return { updated: params.email_ids.length };
  }

  async deleteEmails(params: { email_ids: string[]; permanent?: boolean }) {
    if (params.permanent) {
      await this.client.call(JMAP_USING, [
        [
          "Email/set",
          {
            accountId: this.client.accountId,
            destroy: params.email_ids,
          },
          "d0",
        ],
      ]);
      return { deleted: params.email_ids.length, permanent: true };
    }

    // Move to trash
    const trashId = await this.resolveMailboxId("trash");
    await this.move({ email_ids: params.email_ids, to_mailbox: trashId });
    return { deleted: params.email_ids.length, permanent: false };
  }

  async createMailbox(params: { name: string; parent_id?: string }) {
    const create: Record<string, unknown> = { name: params.name };
    if (params.parent_id) create.parentId = params.parent_id;

    const responses = await this.client.call(JMAP_USING, [
      [
        "Mailbox/set",
        {
          accountId: this.client.accountId,
          create: { mb: create },
        },
        "c0",
      ],
    ]);

    const result = responses[0][1] as { created?: Record<string, { id: string }> };
    const created = result.created?.mb;
    return { id: created?.id, name: params.name };
  }

  async downloadAttachment(params: {
    email_id: string;
    blob_id: string;
    save_to_disk?: boolean;
  }) {
    // Get email to find attachment metadata
    const responses = await this.client.call(JMAP_USING, [
      [
        "Email/get",
        {
          accountId: this.client.accountId,
          ids: [params.email_id],
          properties: ["attachments"],
        },
        "g0",
      ],
    ]);

    const email = (responses[0][1] as { list: Record<string, unknown>[] }).list[0];
    const attachments = (email?.attachments ?? []) as {
      blobId: string;
      name: string;
      type: string;
      size: number;
    }[];
    const attachment = attachments.find((a) => a.blobId === params.blob_id);
    if (!attachment) throw new Error(`Attachment not found: ${params.blob_id}`);

    // Download blob
    const url = this.client.downloadUrl
      .replace("{accountId}", this.client.accountId)
      .replace("{blobId}", params.blob_id)
      .replace("{name}", encodeURIComponent(attachment.name))
      .replace("{type}", encodeURIComponent(attachment.type));

    const res = await fetch(url, {
      headers: { Authorization: `Bearer ${this.client["config"].apiToken}` },
    });
    if (!res.ok) throw new Error(`Blob download failed: ${res.status}`);

    const data = Buffer.from(await res.arrayBuffer());

    // Return inline or save to disk
    const shouldSaveToDisk = params.save_to_disk || data.length > 1_000_000;

    if (shouldSaveToDisk) {
      const dir = join(tmpdir(), "fastmail-mcp");
      await mkdir(dir, { recursive: true });
      const filePath = join(dir, `${params.blob_id}-${attachment.name}`);
      await writeFile(filePath, data);

      return {
        filename: attachment.name,
        content_type: attachment.type,
        size: data.length,
        path: filePath,
      };
    }

    return {
      filename: attachment.name,
      content_type: attachment.type,
      size: data.length,
      data: data.toString("base64"),
    };
  }

  async getIdentities(): Promise<Record<string, unknown>[]> {
    const responses = await this.client.call(JMAP_USING, [
      [
        "Identity/get",
        { accountId: this.client.accountId },
        "i0",
      ],
    ]);

    const result = responses[0][1] as { list: Record<string, unknown>[] };
    return result.list.map((i) => ({
      id: i.id,
      name: i.name,
      email: i.email,
      isDefault: i.isDefault ?? false,
    }));
  }

  // --- Format helpers ---

  private formatEmail(email: Record<string, unknown>, format: "full" | "markdown" | "plain") {
    const bodyValues = email.bodyValues as Record<string, { value: string }> | undefined;

    let body = "";
    let bodyFormat: "html" | "markdown" | "plain" = "plain";

    if (format === "plain") {
      const textParts = email.textBody as { partId: string }[] | undefined;
      if (textParts?.length && bodyValues) {
        body = textParts.map((p) => bodyValues[p.partId]?.value ?? "").join("\n");
      }
      bodyFormat = "plain";
    } else {
      // Get HTML body
      const htmlParts = email.htmlBody as { partId: string }[] | undefined;
      let htmlBody = "";
      if (htmlParts?.length && bodyValues) {
        htmlBody = htmlParts.map((p) => bodyValues[p.partId]?.value ?? "").join("\n");
      }

      if (format === "full") {
        body = htmlBody;
        bodyFormat = "html";
      } else {
        // markdown
        if (htmlBody) {
          body = turndown.turndown(htmlBody);
          bodyFormat = "markdown";
        } else {
          // Fallback to text body
          const textParts = email.textBody as { partId: string }[] | undefined;
          if (textParts?.length && bodyValues) {
            body = textParts.map((p) => bodyValues[p.partId]?.value ?? "").join("\n");
          }
          bodyFormat = "plain";
        }
      }
    }

    return {
      id: email.id,
      threadId: email.threadId,
      mailboxIds: email.mailboxIds,
      subject: email.subject,
      from: email.from,
      to: email.to,
      cc: email.cc,
      bcc: email.bcc,
      replyTo: email.replyTo,
      sentAt: email.sentAt,
      receivedAt: email.receivedAt,
      preview: email.preview,
      body,
      bodyFormat,
      attachments: email.attachments ?? [],
      keywords: email.keywords,
      headers: email.headers,
    };
  }
}

